(function () {
  const join = (L, key) => L.lines.map((l, i) => (i === 0 ? "" : l.p ? "\n\n" : " ") + (l[key] || "")).join("");
  const W = Object.values(PD2.EXAMS || {}).flatMap(E => E.WRITING || []);
  W.forEach(w => {
    const L = PD2.LISTEN[w.id];
    if (!L) return;
    w.model = join(L, "da");
    if (PD2.MODEL_EN) PD2.MODEL_EN[w.id] = join(L, "en");
  });
})();
